INSERT OR IGNORE INTO vehicle_weapons (vehicle_slug, ordinal, name, damage, is_mega_damage, range, rate_of_fire, payload, bonus, note) VALUES
  ('ng-v47-gunbot', 1, 'NG-1010 Heavy Rail Gun', '1D4x10 M.D. per 40 round burst; 2D4x10 M.D. per linked burst and blast with the ion cannon at one target within 1,800 ft (548.6 m)', 1, '5,000 ft (1,524 m)', 'Each burst counts as one melee attack/action', '3,680 rounds (92 bursts) in two side-loaded detachable drums of 1,840 rounds (46 bursts)', NULL, 'Anti-armor and anti-monster, secondarily anti-aircraft and anti-flyer. Weapon 1a, the upper barrel of the fixed-forward nose housing: the upper body turns 360 degrees and tilts 45 degrees to aim it. Its solid shells ignore energy-reflecting armor and magic. Worked by the nose gunner.'),
  ('ng-v47-gunbot', 2, 'NG 2020 Underbarrel Ion Cannon', '1D4x10+4 M.D. per blast', 1, '1,800 ft (548.6 m)', 'Each blast counts as one melee attack/action; links with the rail gun', 'Effectively unlimited', NULL, 'Assault and anti-infantry, secondarily anti-armor and anti-monster. Weapon 1b, the lower barrel under the rail gun, worked by the same gunner.'),
  ('ng-v47-gunbot', 3, 'Shoulder Mini-Missile Launchers (2)', 'By missile type', 1, 'About one mile (1.6 km)', 'One at a time or volleys of two, three or six', '24, 12 in each box launcher', NULL, 'Anti-armor, secondarily anti-aircraft and anti-flyer. Six tubes a shoulder; each launcher tilts out 25 degrees and turns 360 degrees to fire ahead, up or behind. Fired by the second gunner or the pilot.'),
  ('ng-v47-gunbot', 4, 'NG-GL1030A Grenade Cannon (1)', 'Fragmentation 3D6 M.D. to a 12 ft (3.7 m) radius, 1D4x10+3 M.D. per volley of three; high explosive/armor piercing 4D6 M.D. to a 3 ft (0.9 m) radius, 1D6x10+6 per volley; plasma 6D6 M.D. to a 5 ft (1.5 m) radius, 2D4x10+12 per volley; smoke, tear gas and stun/flash grenades too', 1, '1,800 ft (548.6 m)', 'One grenade or a rapid volley of three of one type; each shot or volley counts as one melee action/attack', '120 grenade drum, 40 volleys; one type or a mix of 2-5; a riot control load holds only tear gas, stun/flash and smoke', NULL, 'Assault and anti-personnel, secondarily anti-monster and riot control. A long-barreled rapid-fire launcher on top of the right side, sweeping 220 degrees front to back with a 90 degree vertical arc; fired by the second gunner. Smoke fills a 40 ft (12.2 m) radius. Tear gas fills 25 ft (7.6 m): the unprotected are -10 to strike, parry and dodge, -3 initiative and lose one attack while inside and for 1D6+1 melee rounds after. Stun/flash covers 4 ft (1.2 m): -10 to strike, parry and dodge, -1 initiative and one attack lost for 1D4 melee rounds. A volley of three smoke, gas or flash grenades triples the radius.'),
  ('ng-v61-gunwolf', 1, 'Dual NG-232 Rail Guns', '1D4x10 M.D. per 60 round burst; 1D4 M.D. per round; 2D4x10 M.D. per linked dual burst at one target (one attack). Wood-and-silver rounds do the same figures as S.D.C.', 1, '4,000 ft (1,219 m) conventional and silver-coated rounds; 2,000 ft (610 m) weighted wood rounds with silver rings', 'Each single shot or burst counts as one melee attack', '18,000 rounds total, 150 bursts per gun (300 bursts); printed as four 2,250 round drums, two per gun, which comes to 9,000', NULL, 'Assault and anti-personnel, secondarily defense. Two Gatling-style rail guns on the right forearm, bigger than many vehicle guns. One usually carries M.D. silver-coated rounds (beings that silver harms take the M.D. figure as Hit Point/S.D.C. damage), the other wood rounds ringed with silver, 150 bursts each. Reloading needs loaded drums and special gear or another giant robot: about 15 minutes, 5 for someone with Robot Mechanics or an Operator. The barrel tips carry silver-plated blades for slashing and stabbing when the ammunition is gone: 2D4 M.D.'),
  ('ng-v61-gunwolf', 2, 'Medium NG-223 Chest Rail Gun (1)', '5D6 M.D. per 60 round burst, +4 M.D. within 10 ft (3 m); 1-2 M.D. per round; wood-and-silver rounds 2 S.D.C. a round, 5D6 S.D.C. a burst', 1, '2,000 ft (610 m) conventional and silver-coated rounds; 1,000 ft (305 m) wood rounds with silver rings', 'Each single shot or burst counts as one melee attack', '9,000 rounds, 150 bursts', NULL, 'Assault and anti-personnel, secondarily defense. Built into the chest for close targets and foes held in a grapple; takes the same three kinds of round as the forearm guns.'),
  ('ng-v61-gunwolf', 3, 'NG-I-323 Ion Cannon (1)', '5D6 M.D. per blast', 1, '1,600 ft (488 m)', 'Each blast counts as one melee attack/action', 'Effectively unlimited; 50 blasts per charge on the electric battery model', NULL, 'Anti-armor, secondarily assault. A medium ion pulse cannon on the left forearm, wired to the power supply, for foes that energy can hurt.'),
  ('ng-v61-gunwolf', 4, 'Retractable Mini-Missile Launchers (2)', 'By missile; plasma (1D6x10 M.D.) is standard against creatures vulnerable to fire', 1, 'One mile (1.6 km)', 'One at a time or volleys of two, four or six', '28, 14 per launcher; each retracts to reload after 7, an automatic reload taking one melee round (15 seconds)', NULL, 'Anti-aircraft, anti-missile and anti-flyer, secondarily anti-personnel/monster and anti-armor. In the lower sides of the chest.'),
  ('ng-v61-gunwolf', 5, 'Assault Jaws', 'Soft bite or nip 1D4 M.D.; full strength bite 2D6+3 M.D.; power bite 4D6+6 M.D.; power bite and lock-grip 4D6+6 M.D. with a 01-50% chance to hold on', 1, 'Close combat', 'Each bite or shake counts as one melee attack', NULL, NULL, 'Assault, secondarily defense. Hydraulic jaws with silver-plated teeth that bite through M.D.C. hide and steel and can snag flying power armor. Once locked on, each shake of the head does 2D6 M.D. with no strike roll, or it simply holds for 1D4 M.D., or burns the victim with the mouth flamethrower. To pull free the victim must roll 18 or better to parry and takes 3D6 M.D.; the grip lets go by itself at the end of the melee round.'),
  ('ng-v61-gunwolf', 6, 'Heavy Flamethrower', '1D4x10 M.D. to the target and anyone within 10 ft (3 m); 5D6 M.D. on diesel or gasoline', 1, '400 ft (122 m)', 'Each burst counts as one melee action/attack', '48 bursts from an 80 gallon (302 liter) reserve; refuel with military napalm, or diesel or gasoline at reduced damage', NULL, 'Anti-structure, secondarily anti-personnel. The Beachmaster''s flamethrower, fired from the back of the mouth; meant for creatures that fear or are hurt by fire, and has unsettled lesser demons. Valves seal it under water.'),
  ('ng-v61-gunwolf', 7, 'Eye Lasers (2)', '2D6 M.D. per blast; 4D6 M.D. linked at one target', 1, '1,200 ft (366 m)', 'Each single or linked blast counts as one melee attack', 'Effectively unlimited; 50 blasts per charge each on the electric battery model', NULL, 'Anti-armor, secondarily assault. One short-ranged laser in each eye socket, also for creatures vulnerable to light.'),
  ('ng-v61-gunwolf', 8, 'Wolf''s Howl Anti-Monster System (NG-RS-X Scrambler)', 'None; disorients instead', 0, 'Short range', NULL, NULL, NULL, 'Experimental. The spine fins pour out subsonic and ultrasonic pulses at once. Creatures with keen hearing (Xiticix, Dog Boys and other mutant animals, some D-Bees, vampires) suffer -10% Spd, -1 attack per melee, -3 Perception, -2 initiative, -1 to parry and dodge, -2 to pull punch and -15% on all skills. It also fills nearby radio, radar and sonar with static: -15% to Sensory Equipment and radio skill rolls.'),
  ('ng-v67-grizzly', 1, 'NG-I-367 Ion Cannons (2)', '5D6 M.D. per blast; 1D6x10 M.D. per linked blast at one target', 1, '2,000 ft (610 m)', 'Each single or linked blast counts as one melee attack', 'Effectively unlimited; wired to the nuclear supply', NULL, 'Anti-armor and assault, secondarily anti-monster and anti-personnel. The standard pair in the top turret behind the head: a full-circle turret with a 120 degree vertical arc for the guns and each swings 45 degrees sideways on its own, so they can link or split between two targets. Worked by the gunner in the head, who also fires the head missiles and the shoulder tubes.'),
  ('ng-v67-grizzly', 2, 'Alternate Top Turret: Rail Guns (2)', '1D4x10 M.D. per 60 round burst; 1D4 M.D. per round; 2D4x10 M.D. per linked dual burst at one target (one attack). Wood-and-silver rounds do the same figures as S.D.C.', 1, '4,000 ft (1,219 m) conventional and silver-coated rounds; 2,000 ft (610 m) weighted wood rounds with silver rings', 'Each single shot or burst counts as one melee attack', '18,000 rounds total, 150 bursts per gun (300 bursts); printed as four 2,250 round drums, two per gun, which comes to 9,000', NULL, 'Assault and anti-personnel, secondarily defense. Replaces the ion cannons for buyers expecting supernatural foes, firing conventional, silver or wood rounds as the Gunwolf''s rail guns do. Reloading needs loaded drums and special gear or another giant robot: about 15 minutes, 5 for someone with Robot Mechanics or an Operator.'),
  ('ng-v67-grizzly', 3, 'Armor Buster, Long-Range Laser Cannon (1)', '6D6+4 M.D. per blast', 1, '4,000 ft (1,219 m)', 'Single blasts only', 'Effectively unlimited', NULL, 'Anti-armor and assault, secondarily anti-monster and anti-personnel. The Big Gun on the left shoulder, fired by the pilot; it rotates through 360 degrees vertically and can spin to fire behind, but the upper torso must turn to bring it on target. It has no alternate.'),
  ('ng-v67-grizzly', 4, 'Mini-Missile Box Launchers (2)', 'By missile; high explosive (1D4x10 M.D.) and plasma (1D6x10 M.D.) are standard; smoke and Hex mini-missiles can join or replace the load', 1, 'One mile (1.6 km)', 'One at a time or volleys of 2, 3, 4, 5, 6 or 7', '70, 35 per launcher; automatic reload', NULL, 'Anti-aircraft, anti-missile and anti-flyer, secondarily anti-personnel/monster and anti-armor. Pepper-box launchers on each side of the head, aimed by turning it (120 degrees left and right, 45 degree vertical arc); fired by the gunner in the head. No alternate.'),
  ('ng-v67-grizzly', 5, 'Shoulder Flare Chaff Launchers (6)', 'None; a chaff cloud', 0, '6,000 ft (1,829 m); 2,000 ft (610 m) for grenades', 'One at a time or volleys of 2, 3, 4, 5 or 6', '30, five per tube; the grenade alternate is the same', NULL, 'Anti-missile, secondarily anti-flyer. Three tubes in each upper shoulder burst at a set point into a 30 ft (9.1 m) cloud, +10 ft (3 m) per extra rocket in the volley, lasting two melee rounds. It has a 10% chance per rocket in the volley (60% at most) to set off an incoming missile volley, which disperses the cloud. A flyer inside is -6 Perception, -3 initiative, -5 to strike, -2 to parry and dodge, loses one attack, loses laser and optic targeting bonuses and is -20% to Sensory Equipment and Piloting for the round. ALTERNATE loads, usually 10 smoke and 20 Hex: smoke blinds anyone in the cloud for 1D4+4 minutes (half in strong wind); a Hex grenade releases an acid smoke over 20 ft (6.1 m) for 1D4+3 melee rounds, and anyone breathing it saves vs non-lethal toxin at 16 or suffers -2 attacks, -6 Perception, -4 initiative, -2 to strike, parry, dodge and disarm, half Spd and -20% skills for 1D6+2 minutes, then half that for 2D4x10 minutes (a save halves the penalties for 1D4 melee rounds). Mega-Damage mortals, dragons, creatures of magic and most supernatural beings get halved penalties or durations, keen-nosed ones (Loup Garou, Wendigo, werebeasts) the full initial effect; the undead, Elementals, fire-breathers and the sealed are immune. Hex costs 2,500 credits a grenade, 7,500 as a 3,000 ft (914 m) mini-missile; poor availability. Techno-Wizard flares can also be fired, though NG does not sell them.'),
  ('ng-v67-grizzly', 6, 'Belly Gun Type One: Heavy, Long-Range Rail Gun (1)', '1D4x10 M.D. per 60 round burst; 1D4 M.D. per round; 1D6x10 M.D. at one target linked with the medium belly gun (one attack). Wood-and-silver rounds do the same figures as S.D.C.', 1, '4,000 ft (1,219 m) conventional and silver-coated rounds; 2,000 ft (610 m) wood rounds with silver rings', 'Each single shot or burst counts as one melee attack', '9,000 rounds, 150 bursts', NULL, 'Assault and anti-personnel, secondarily defense. One of the two standard belly guns; both retract inside for hand to hand combat and cannot fire while retracted.'),
  ('ng-v67-grizzly', 7, 'Belly Gun Type Two: Medium NG-223 Rail Gun (1)', '5D6 M.D. per 60 round burst, +4 M.D. within 10 ft (3 m); 1-2 M.D. per round; wood-and-silver rounds 2 S.D.C. a round, 5D6 S.D.C. a burst', 1, '2,000 ft (610 m) conventional and silver-coated rounds; 1,000 ft (305 m) wood rounds with silver rings', 'Each single shot or burst counts as one melee attack', '12,000 rounds, 200 bursts', NULL, 'Assault and anti-personnel, secondarily defense. The close-range belly gun, for foes in a grapple; the Gunwolf''s chest gun with a bigger magazine.'),
  ('ng-v67-grizzly', 8, 'Alternate Belly Guns: Dual Ion Guns', '4D6+4 M.D. per blast; 1D4x10+2 M.D. per linked blast at one target', 1, '1,600 ft (488 m)', 'Each single or linked blast counts as one melee attack', 'Effectively unlimited', NULL, 'Anti-personnel and assault, secondarily anti-monster and defense. 178,000 credits the pair. Replaces either belly gun or both. The book''s linked-fire line here says laser guns; it is the ion pair.'),
  ('ng-v67-grizzly', 9, 'Alternate Belly Guns: Dual Laser Guns', '4D6 M.D. per blast; 1D4x10 M.D. per linked blast at one target', 1, '2,000 ft (610 m)', 'Each single or linked blast counts as one melee attack', 'Effectively unlimited', NULL, 'Anti-personnel and assault, secondarily anti-monster and defense. 155,000 credits the pair. Replaces either belly gun or both. The book''s linked-fire line here says ion guns; it is the laser pair.'),
  ('ng-v67-grizzly', 10, 'Alternate Belly Guns: Dual Flamethrowers', 'As the Gunwolf''s heavy flamethrower: 1D4x10 M.D. to the target and anyone within 10 ft (3 m)', 1, 'As the Gunwolf''s: 400 ft (122 m)', 'Each burst counts as one melee action/attack', '80 gallon (302 liter) reserve', NULL, '140,000 credits. Printed as the same as the Gunwolf''s or Beachmaster''s flamethrower; replaces either belly gun or both.'),
  ('ng-v67-grizzly', 11, 'Standard Right Forearm Weapon: Flamethrower (1)', '1D4x10 M.D. to the target and anyone within 10 ft (3 m); 3D6 M.D. on diesel or gasoline', 1, '200 ft (61 m)', 'Each burst counts as one melee action/attack', '10 bursts from a 20 gallon (76 liter) reserve; refuel with military napalm, or diesel or gasoline at reduced damage', NULL, 'Anti-structure and anti-personnel, secondarily anti-monster. 50,000 credits as a modular attachment. Waterproof; valves seal it under water. Anyone caught in a bunker, cave or unsealed vehicle without environmental gear or air must save vs poison or fall unconscious for 1D4 melee rounds.'),
  ('ng-v67-grizzly', 12, 'Alternate Right Forearm: NG-L-555 Multiple-Target Laser', '1D6 M.D. to each of up to five targets', 1, '1,000 ft, printed with (61 m), the metric of 200 ft', 'Each volley of up to five simultaneous shots counts as one melee action/attack', 'Effectively unlimited; tied to the power supply', NULL, 'Anti-personnel and assault, secondarily anti-missile and defense. 115,000 credits. New and experimental, built from plans NG stole from Wilk''s, and offered only on the Grizzly so far; it looks much like the searchlight. It marks up to five targets across a 45 degree spread and fires at all of them at once; it cannot concentrate on one target unless that target is 20-40 ft (6.1-12.2 m) wide, and even then the hits scatter.'),
  ('ng-v67-grizzly', 13, 'Standard Left Forearm Weapon: Wooden Spike Thrower (1)', '2D6 Hit Points/S.D.C. per stake, typically double and direct to Hit Points against vampires and others vulnerable to wood; 4D6 S.D.C. per burst of three, 1D6x10 S.D.C. per burst of six', 0, '1,200 ft (366 m)', 'A single stake or a burst of 3-6 counts as one melee attack/action; only a single stake can be an aimed shot', '36 stakes; four more loaded by hand per melee round, and a locker in the pilot compartment holds a dozen (or four mini-missiles)', NULL, 'Anti-monster and assault, secondarily anti-personnel. Fires 2 ft (0.6 m) wooden stakes, or stakes of bone, stone, iron or silver of the same shape; NG makes those to order in 1D4+3 weeks, sometimes with a minimum quantity.'),
  ('ng-v67-grizzly', 14, 'Alternate Left Forearm: Grenade Launcher (1)', 'By grenade type', 1, '1,200 ft (366 m)', 'One at a time or volleys of 2', '42; retracts to reload after 7, an automatic reload taking one melee round (15 seconds)', NULL, 'Anti-armor and anti-fortification, secondarily anti-personnel and anti-monster. 75,000 credits plus the grenades.'),
  ('ng-v67-grizzly', 15, 'Alternate Left Forearm: Mini-Missile Box Launcher (1)', 'By missile; plasma (1D6x10 M.D.) is standard', 1, 'One mile (1.6 km)', 'One at a time or volleys of 2, 3 or 4', '12', NULL, 'Anti-aircraft, anti-missile and anti-flyer, secondarily anti-personnel/monster and anti-armor. 85,000 credits plus the missiles.');

-- Read the result back. This script asserts its OWN rows and nothing else.
SELECT 'all 3 machines are in' AS assertion, count(*) AS got, 3 AS want
  FROM vehicles WHERE slug IN ('ng-v47-gunbot', 'ng-v61-gunwolf', 'ng-v67-grizzly');
SELECT 'their 54 locations are in' AS assertion, count(*) AS got, 54 AS want
  FROM vehicle_locations WHERE vehicle_slug IN ('ng-v47-gunbot', 'ng-v61-gunwolf', 'ng-v67-grizzly');
SELECT 'their 27 weapon entries are in' AS assertion, count(*) AS got, 27 AS want
  FROM vehicle_weapons WHERE vehicle_slug IN ('ng-v47-gunbot', 'ng-v61-gunwolf', 'ng-v67-grizzly');
SELECT 'each main body location equals mdc_main_body' AS assertion, count(*) AS got, 0 AS want
  FROM vehicles v JOIN vehicle_locations l ON l.vehicle_slug = v.slug AND l.location = 'Main Body'
  WHERE v.slug IN ('ng-v47-gunbot', 'ng-v61-gunwolf', 'ng-v67-grizzly') AND l.mdc IS NOT NULL AND v.mdc_main_body IS NOT NULL AND l.mdc <> v.mdc_main_body;

